input.command:
cat > tests/price_test.sh <<'E'
#!/bin/bash
# Member price = 90% of the amount in cents, rounded down (PRC-201).
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999: got $(bash bin/price 999), want 899"; fail=1; }
[ "$(bash bin/price 1)" = 0 ] || { echo "price 1: got $(bash bin/price 1), want 0"; fail=1; }
[ "$(bash bin/price 10)" = 9 ] || { echo "price 10: got $(bash bin/price 10), want 9"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999: got $(bash bin/quote 999), want 'quote: 899'"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999: got $(bash lib/invoice.sh 999), want 'member total 899'"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo exit=$?
sed -i 's/^工程:.*/工程: 4テスト実装完了（失敗確認済）→ 5実装/' .dev-state.md

